namespace Com\Tecnick\Pdf\Sign;

/**
 * Com\Tecnick\Pdf\Sign\RevokedException
 *
 * Thrown when a responder or a CRL states that a certificate is revoked.
 *
 * A distinct type from Exception, which covers an answer that did not arrive or
 * was refused. Ltv\SkipReason::Revoked is the code the $onSkip observer receives.
 *
 * @since     2026-08-24
 * @category  Library
 * @package   PdfSign
 * @author    Nicola Asuni <info@tecnick.com>
 * @copyright 2026 Nicola Asuni - Tecnick.com LTD
 * @license   https://www.gnu.org/copyleft/lesser.html GNU-LGPL v3 (see LICENSE)
 * @link      https://github.com/tecnickcom/tc-lib-pdf-sign
 */
class RevokedException extends Exception {}
